css:
.glocalsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a1f2d;
    background: linear-gradient(160deg, #fdf3ee 0%, #f6e9f0 100%);
    border-radius: 18px;
}

.glocalsim-container * {
    box-sizing: border-box;
}

.glocalsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #7a1f3d 0%, #b8395a 48%, #e0653f 100%);
    color: #fff5ef;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(122, 31, 61, 0.30);
}

.glocalsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.glocalsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffe3cf;
    background: rgba(255, 255, 255, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.glocalsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #fde6da;
}

.glocalsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #7a1f3d;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.glocalsim-period-counter #currentDay,
.glocalsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b8395a;
}

.glocalsim-round-name {
    background: #f6d9c9;
    color: #7a1f3d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.glocalsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a4b12;
    background: #fbeccf;
    padding: 4px 12px;
    border-radius: 999px;
}

.glocalsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.glocalsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #f0dbe2;
    box-shadow: 0 4px 14px rgba(122, 31, 61, 0.07);
    border-top: 4px solid #b8395a;
}

.glocalsim-card-share { border-top-color: #c0392b; }
.glocalsim-card-consistency { border-top-color: #1f7a8c; }
.glocalsim-card-roi { border-top-color: #2e7d32; }
.glocalsim-card-agility { border-top-color: #c98a16; }

.glocalsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a6b75;
}

.glocalsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #7a1f3d;
}

.glocalsim-card-share .glocalsim-value { color: #c0392b; }
.glocalsim-card-consistency .glocalsim-value { color: #1f7a8c; }
.glocalsim-card-roi .glocalsim-value { color: #2e7d32; }
.glocalsim-card-agility .glocalsim-value { color: #c98a16; }

.glocalsim-sublabel {
    font-size: 0.76rem;
    color: #9a7c85;
    line-height: 1.35;
}

.glocalsim-share-up .glocalsim-value { color: #2e7d32; }
.glocalsim-share-down .glocalsim-value { color: #c0392b; }

.glocalsim-consistency-breach { border-top-color: #c0392b; }
.glocalsim-consistency-breach .glocalsim-value { color: #c0392b; }

.glocalsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #7a1f3d;
    color: #fdeee6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.glocalsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.glocalsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e0653f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(122, 31, 61, 0.06);
}

.glocalsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.glocalsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #7a1f3d;
    margin-bottom: 6px;
}

.glocalsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3640;
}

.glocalsim-briefing-text strong { color: #2e7d32; }
.glocalsim-briefing-text em { color: #c0392b; font-style: italic; }

.glocalsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #f0dbe2;
    box-shadow: 0 4px 14px rgba(122, 31, 61, 0.07);
}

.glocalsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #7a1f3d;
    border-bottom: 2px solid #f6e3e9;
    padding-bottom: 8px;
}

.glocalsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #5a3744;
    margin: 14px 0 6px;
}

.glocalsim-container select,
.glocalsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #e3c3cd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdf6f8;
    color: #2a1f2d;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.glocalsim-container select:focus,
.glocalsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b8395a;
    box-shadow: 0 0 0 3px rgba(184, 57, 90, 0.15);
}

.glocalsim-container select option {
    background-color: #ffffff;
    color: #2a1f2d;
}

.glocalsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b8395a;
}

.glocalsim-range-readout,
.glocalsim-split-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #a8442a;
    margin-top: 4px;
}

.glocalsim-range-readout span:last-child {
    color: #2e7d32;
    font-weight: 800;
}

.glocalsim-split-readout {
    background: #fbeede;
    border: 1px solid #f3dcc2;
    border-radius: 9px;
    padding: 8px 12px;
    margin-top: 6px;
    color: #5a3744;
}

.glocalsim-split-readout #globalSpendReadout {
    color: #1f7a8c;
    font-weight: 800;
}

.glocalsim-split-readout #localSpendReadout {
    color: #c0392b;
    font-weight: 800;
}

.glocalsim-split-sep {
    color: #c0a0aa;
    margin: 0 4px;
}

.glocalsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.glocalsim-container .btn-primary {
    background: linear-gradient(135deg, #b8395a 0%, #e0653f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(184, 57, 90, 0.30);
}

.glocalsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.glocalsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #e3c3cd;
    color: #8a6b75;
}

.glocalsim-coach {
    background: #7a1f3d;
    color: #fdeee6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(122, 31, 61, 0.24);
}

.glocalsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f3b39a;
    margin-bottom: 8px;
}

.glocalsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.glocalsim-coach-body strong { color: #ffd98a; }
.glocalsim-coach-body em { color: #ffc1ad; font-style: italic; }

.glocalsim-history,
.glocalsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #f0dbe2;
    box-shadow: 0 4px 14px rgba(122, 31, 61, 0.07);
}

.glocalsim-history h3,
.glocalsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #7a1f3d;
}

.glocalsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3640;
}

.glocalsim-container table#usfHistoryTable th {
    background: #f9e7ec;
    color: #7a1f3d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #f0d3db;
}

.glocalsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f6e7ec;
}

.glocalsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fdf6f8;
}

.glocalsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .glocalsim-container {
        padding: 14px;
    }
    .glocalsim-header h1 {
        font-size: 1.7rem;
    }
    .glocalsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .glocalsim-value {
        font-size: 2rem;
    }
    .glocalsim-clock {
        margin-left: 0;
    }
    .glocalsim-period-counter {
        font-size: 0.88rem;
    }
    .glocalsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .glocalsim-split-readout {
        flex-wrap: wrap;
    }
    .glocalsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light modal, glocalsim) ---- */
.glocalsim-completion { padding: 8px 4px 4px; }
.glocalsim-cm-head { text-align: center; margin-bottom: 16px; }
.glocalsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6f6a; }
.glocalsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a9b96; }
.glocalsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #14213d; }
.glocalsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.glocalsim-cm-yes { background: rgba(47,111,106,0.14); color: #256b64; border: 1px solid rgba(47,111,106,0.5); }
.glocalsim-cm-no { background: rgba(199,154,60,0.16); color: #8a6a1f; border: 1px solid rgba(199,154,60,0.5); }
.glocalsim-cm-fail { background: rgba(192,57,43,0.12); color: #b0392b; border: 1px solid rgba(192,57,43,0.45); }
.glocalsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.glocalsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(20,33,61,0.06); border: 1px solid rgba(20,33,61,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.glocalsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #23304f; }
.glocalsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.glocalsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14213d; }
.glocalsim-cm-insights { margin: 0; padding-left: 20px; }
.glocalsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

