(function() {
    'use strict';

    class GlocalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Glocal Balancing Act`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Aurelia Türkiye, TRY in millions).
            this.START_SHARE = 19.0;         // Bella value share, #2
            this.SHARE_FLOOR = 18.0;         // share defence floor
            this.START_CONSISTENCY = 88;     // HQ-scored Brand Consistency Index
            this.CONSISTENCY_FLOOR = 80;     // HQ review floor — autonomy at risk below this
            this.START_ROI = 40;             // Marketing ROI index (0–100), low headroom
            this.START_AGILITY = 22;         // Marketing Agility Index (0–100), low headroom
            this.BUDGET_CAP = 240;           // ₺240M frozen H2 budget — no top-up
            this.MANDATE_PCT = 70;           // HQ ≥70% global media-weight mandate
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    share: this.START_SHARE,
                    consistency: this.START_CONSISTENCY,
                    roi: this.START_ROI,
                    agility: this.START_AGILITY,
                    budgetUsed: 0,
                    consistencyBreached: false,
                    shareLost: false,
                    opaque: false,
                    shareHistory: [this.START_SHARE],
                    consistencyHistory: [this.START_CONSISTENCY],
                    roiHistory: [this.START_ROI],
                    agilityHistory: [this.START_AGILITY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    signal: `format`,
                    mismatch: `packaging`,
                    orientation: 25,
                    globalPct: 90,
                    localUse: `hold`,
                    negotiate: `comply`,
                    response: `pricewar`,
                    speed: 25,
                    currency: `partial`,
                    hqMsg: `defensive`,
                    pitch: `zerosum`,
                    scorecard: `shareonly`,
                    autonomy: `defer`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sig = document.getElementById(`signalInput`);
                const mis = document.getElementById(`mismatchInput`);
                const ori = document.getElementById(`orientationInput`);
                if (sig) decisions.signal = sig.value;
                if (mis) decisions.mismatch = mis.value;
                if (ori) decisions.orientation = parseInt(ori.value, 10);
                if (!Number.isFinite(decisions.orientation) || decisions.orientation < 0 || decisions.orientation > 100) {
                    warn(`warn_orientation_range`); return false;
                }
            } else if (round === 2) {
                const gp = document.getElementById(`globalPctInput`);
                const lu = document.getElementById(`localUseInput`);
                const ng = document.getElementById(`negotiateInput`);
                if (gp) decisions.globalPct = parseFloat(gp.value);
                if (lu) decisions.localUse = lu.value;
                if (ng) decisions.negotiate = ng.value;
                if (!Number.isFinite(decisions.globalPct) || decisions.globalPct < 0 || decisions.globalPct > 100) {
                    warn(`warn_global_range`); return false;
                }
            } else if (round === 3) {
                const rsp = document.getElementById(`responseInput`);
                const sp = document.getElementById(`speedInput`);
                const cur = document.getElementById(`currencyInput`);
                const hq = document.getElementById(`hqMsgInput`);
                if (rsp) decisions.response = rsp.value;
                if (sp) decisions.speed = parseInt(sp.value, 10);
                if (cur) decisions.currency = cur.value;
                if (hq) decisions.hqMsg = hq.value;
                if (!Number.isFinite(decisions.speed) || decisions.speed < 0 || decisions.speed > 100) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const sc = document.getElementById(`scorecardInput`);
                const au = document.getElementById(`autonomyInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (sc) decisions.scorecard = sc.value;
                if (au) decisions.autonomy = au.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas move the four twin-engine dials. shareDelta in share points (×0.1 each step
            // below is added directly); the others on a 0–100 index.
            let shareDelta = 0, consistencyDelta = 0, roiDelta = 0, agilityDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose market orientation — read where the rival is taking share and the
                // single biggest global/local mismatch. No spend yet.
                switch (d.signal) {
                    case `ramadan`: agilityDelta += 12; shareDelta += 0.3; coachKey = `coach_r1_ramadan`; break;
                    case `format`: agilityDelta += 3; coachKey = `coach_r1_format`; break;
                    case `priceonly`: agilityDelta -= 4; roiDelta -= 4; coachKey = `coach_r1_priceonly`; break;
                    case `ignore`: agilityDelta -= 10; shareDelta -= 0.4; coachKey = `coach_r1_ignore`; break;
                }

                switch (d.mismatch) {
                    case `occasion`: agilityDelta += 10; consistencyDelta += 1; if (d.signal === `ramadan`) coachKey = `coach_r1_sharp`; break;
                    case `packaging`: agilityDelta += 2; break;
                    case `language`: agilityDelta += 1; break;
                    case `none`: agilityDelta -= 10; coachKey = `coach_r1_nomismatch`; break;
                }

                if (d.orientation >= 60) { agilityDelta += 8; }
                else if (d.orientation <= 25) { agilityDelta -= 8; coachKey = `coach_r1_lowori`; }

                summaryKey = (d.signal === `ramadan` && d.mismatch === `occasion`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate the frozen ₺240M across the standardized global campaign and local
                // adaptation. This round commits the full budget.
                const gp = d.globalPct;
                spend = this.BUDGET_CAP; // the whole frozen budget is now committed

                // Brand Consistency tracks how close you stay to the global standard. Holding the
                // ≥70% mandate protects it; dropping global weight erodes it; below ~55% breaches
                // the 80 floor (HQ review). dualduty asset partly offsets the consistency cost.
                const belowMandate = this.MANDATE_PCT - gp; // positive if under the 70% mandate
                if (gp >= this.MANDATE_PCT) {
                    consistencyDelta += 1;
                } else {
                    consistencyDelta -= belowMandate * 0.55; // e.g. 55% global → -8.25
                }

                // Local share defence: the local-adaptation budget (240 - global) buys share, but
                // ONLY if it actually funds local relevance. localPct = 100 - gp.
                const localPct = 100 - gp;

                switch (d.localUse) {
                    case `dualduty`:
                        // The standardized asset adapted for Ramadan — one lira buys both engines.
                        shareDelta += 0.9 + localPct * 0.018; // strong share even at 30% local
                        consistencyDelta += 6;                // the asset stays on-brand → protects consistency
                        roiDelta += 12; agilityDelta += 10;
                        coachKey = `coach_r2_dualduty`;
                        break;
                    case `value`:
                        // A separate value-tier line defends share but fragments the brand.
                        shareDelta += 0.4 + localPct * 0.022;
                        consistencyDelta -= 3; roiDelta += 4; agilityDelta += 4;
                        coachKey = `coach_r2_value`;
                        break;
                    case `trade`:
                        // Deep trade promotions: a short-term share bump that destroys margin (ROI).
                        shareDelta += 0.3 + localPct * 0.020;
                        roiDelta -= 10; consistencyDelta -= 2; agilityDelta += 2;
                        coachKey = `coach_r2_trade`;
                        break;
                    case `hold`:
                        // Maximally compliant: cede the Ramadan window to the rival.
                        shareDelta -= 0.8; agilityDelta -= 8; roiDelta -= 2;
                        coachKey = `coach_r2_hold`;
                        break;
                }

                // Negotiation / transparency with HQ on any deviation.
                if (gp < this.MANDATE_PCT) {
                    switch (d.negotiate) {
                        case `caseup`:
                            // Transparent, defensible deviation — HQ flexes, consistency hit softened.
                            consistencyDelta += 4; agilityDelta += 4; coachKey = `coach_r2_caseup`;
                            break;
                        case `comply`:
                            // Says "don't deviate" but global% is under the mandate — incoherent.
                            consistencyDelta -= 2; coachKey = `coach_r2_incoherent`;
                            break;
                        case `silent`:
                            // Opaque deviation — the tracker catches it later (Common Error 5).
                            ds.opaque = true; consistencyDelta -= 6; agilityDelta -= 4;
                            coachKey = `coach_r2_silent`;
                            break;
                    }
                } else if (d.negotiate === `silent`) {
                    // Compliant but choosing silence as a posture still erodes trust.
                    consistencyDelta -= 1;
                }

                const goodSplit = (gp >= 60 && gp <= this.MANDATE_PCT && d.localUse === `dualduty` && d.negotiate !== `silent`);
                summaryKey = goodSplit ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Sudden shift: rival cuts another 8% and goes viral; HQ queries the consistency
                // trend. Reallocate within the frozen budget — speed vs perfection, margin under
                // the lira, and what to tell HQ. No new money: overspend on a price war just
                // wastes the frozen budget.
                switch (d.response) {
                    case `dualfast`:
                        shareDelta += 0.9; agilityDelta += 12; roiDelta += 6; consistencyDelta += 2;
                        coachKey = `coach_r3_dualfast`;
                        break;
                    case `pricewar`:
                        // Defends share on price alone — burns margin under the weak lira.
                        shareDelta += 0.5; roiDelta -= 12; agilityDelta += 2; spend += 20;
                        coachKey = `coach_r3_pricewar`;
                        break;
                    case `standpat`:
                        // The mandate says don't move — cedes the in-season window.
                        shareDelta -= 1.0; agilityDelta -= 10;
                        coachKey = `coach_r3_standpat`;
                        break;
                    case `perfect`:
                        // A perfect plan delivered after the window closes — agility forfeited.
                        shareDelta -= 0.7; agilityDelta -= 12; consistencyDelta += 1;
                        coachKey = `coach_r3_perfect`;
                        break;
                }

                // Speed of in-season response — agility prizes a good-enough plan in week three.
                if (d.speed >= 60) { agilityDelta += 8; shareDelta += 0.2; }
                else if (d.speed <= 25) { agilityDelta -= 8; shareDelta -= 0.3; coachKey = `coach_r3_slow`; }

                // Currency discipline — re-run ROI in today's lira (Common Error 4).
                switch (d.currency) {
                    case `rerun`: roiDelta += 12; agilityDelta += 3; if (d.response === `dualfast`) coachKey = `coach_r3_margin`; break;
                    case `partial`: roiDelta += 2; break;
                    case `ignore`: roiDelta -= 12; coachKey = `coach_r3_macroblind`; break;
                }

                // What you tell HQ about the falling consistency score (Common Error 5).
                switch (d.hqMsg) {
                    case `transparent`: consistencyDelta += 6; agilityDelta += 4; break;
                    case `defensive`: consistencyDelta -= 4; coachKey = `coach_r3_defensive`; break;
                    case `ignore`: ds.opaque = true; consistencyDelta -= 8; coachKey = `coach_r3_hqignore`; break;
                }

                summaryKey = (d.response === `dualfast` && d.currency === `rerun` && d.hqMsg === `transparent`) ? `sum_r3_good`
                    : (d.response === `pricewar` || d.currency === `ignore` ? `sum_r3_macro` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend agility & lock the plan. Frame the twin engines, commit a scorecard, and
                // protect the subsidiary's autonomy.
                switch (d.pitch) {
                    case `complementary`: agilityDelta += 14; consistencyDelta += 4; shareDelta += 0.2; coachKey = `coach_r4_complementary`; break;
                    case `zerosum`: agilityDelta -= 6; consistencyDelta -= 2; coachKey = `coach_r4_zerosum`; break;
                    case `compliance`: agilityDelta -= 4; shareDelta -= 0.3; coachKey = `coach_r4_compliance`; break;
                }

                switch (d.scorecard) {
                    case `tracked`: agilityDelta += 10; roiDelta += 6; consistencyDelta += 2; break;
                    case `shareonly`: agilityDelta += 2; consistencyDelta -= 2; coachKey = `coach_r4_shareonly`; break;
                    case `none`: agilityDelta -= 10; roiDelta -= 4; coachKey = `coach_r4_noscore`; break;
                }

                switch (d.autonomy) {
                    case `earn`: agilityDelta += 6; consistencyDelta += 3; coachKey = (d.pitch === `complementary`) ? `coach_r4_earn` : coachKey; break;
                    case `grab`: consistencyDelta -= 8; agilityDelta -= 4; coachKey = `coach_r4_grab`; break;
                    case `defer`: shareDelta -= 0.4; agilityDelta -= 6; coachKey = `coach_r4_defer`; break;
                }

                // Conviction nudges agility.
                agilityDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.pitch === `complementary` && d.scorecard === `tracked` && d.autonomy === `earn`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting — the frozen budget cannot be topped up.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));

            // Apply deltas with realistic bounds.
            ds.share = Math.max(10, Math.min(28, Math.round((ds.share + shareDelta) * 10) / 10));
            ds.consistency = Math.max(50, Math.min(100, Math.round(ds.consistency + consistencyDelta)));
            ds.roi = Math.max(0, Math.min(100, Math.round(ds.roi + roiDelta)));
            ds.agility = Math.max(0, Math.min(100, Math.round(ds.agility + agilityDelta)));

            // Breach / loss flags.
            if (ds.consistency < this.CONSISTENCY_FLOOR) ds.consistencyBreached = true;
            if (ds.share < this.SHARE_FLOOR) ds.shareLost = true;

            ds.shareHistory.push(ds.share);
            ds.consistencyHistory.push(ds.consistency);
            ds.roiHistory.push(ds.roi);
            ds.agilityHistory.push(ds.agility);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                share: ds.share,
                shareDelta: Math.round(shareDelta * 10) / 10,
                consistency: ds.consistency,
                consistencyDelta: Math.round(consistencyDelta),
                roi: ds.roi,
                roiDelta: Math.round(roiDelta),
                agility: ds.agility,
                agilityDelta: Math.round(agilityDelta),
                budgetUsed: ds.budgetUsed,
                consistencyBreached: ds.consistencyBreached,
                opaque: ds.opaque,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

