            const recompute = function() {
                let pct = parseFloat(gp ? gp.value : 70);
                if (!Number.isFinite(pct)) pct = 70;
                pct = Math.max(0, Math.min(100, pct));
                const g = Math.round(self.BUDGET_CAP * pct / 100);
                const l = self.BUDGET_CAP - g;
                if (globalReadout) globalReadout.textContent = `₺` + g + `M`;
                if (localReadout) localReadout.textContent = `₺` + l + `M`;
                if (globalReadout) globalReadout.style.color = (pct < self.MANDATE_PCT) ? `#c0392b` : ``;
            };
            if (gp) gp.addEventListener(`input`, recompute);
            recompute();
        }

