        _composite(ds) {
            const share = ds.share;
            const consistency = ds.consistency;
            const roi = ds.roi;
            const agility = ds.agility;
            const shareNorm = Math.max(0, Math.min(100, (share - 10) / 18 * 100));
            const composite = Math.round(shareNorm * 0.28 + consistency * 0.24 + roi * 0.20 + agility * 0.28);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="glocalsim-cm-badge glocalsim-cm-yes">` + T(`cm_sound`) + `</span>`
                : `<span class="glocalsim-cm-badge glocalsim-cm-no">` + T(`cm_notsound`) + `</span>`;
            let failBadges = ``;
            if (s.heldConsistency === false) failBadges += ` <span class="glocalsim-cm-badge glocalsim-cm-fail">` + T(`cm_breach`) + `</span>`;
            if (s.opaque) failBadges += ` <span class="glocalsim-cm-badge glocalsim-cm-fail">` + T(`cm_opaque`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="glocalsim-cm-metric"><span class="glocalsim-cm-mv">` + Math.round(s.share || 0) + `</span><span class="glocalsim-cm-ml">` + T(`cm_m_share`) + `</span></div>`
                + `<div class="glocalsim-cm-metric"><span class="glocalsim-cm-mv">` + Math.round(s.consistency || 0) + `</span><span class="glocalsim-cm-ml">` + T(`cm_m_consistency`) + `</span></div>`
                + `<div class="glocalsim-cm-metric"><span class="glocalsim-cm-mv">` + Math.round(s.roi || 0) + `</span><span class="glocalsim-cm-ml">` + T(`cm_m_roi`) + `</span></div>`
                + `<div class="glocalsim-cm-metric"><span class="glocalsim-cm-mv">` + Math.round(s.agility || 0) + `</span><span class="glocalsim-cm-ml">` + T(`cm_m_agility`) + `</span></div>`;
            return ``
                + `<div class="glocalsim-completion">`
                +   `<div class="glocalsim-cm-head">`
                +     `<div class="glocalsim-cm-score">` + score + `<span class="glocalsim-cm-score-max">/100</span></div>`
                +     `<div class="glocalsim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="glocalsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="glocalsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="glocalsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const share = ds.share;
            const consistency = ds.consistency;
            const roi = ds.roi;
            const agility = ds.agility;

            const heldShare = share >= this.SHARE_FLOOR;
            const heldConsistency = consistency >= this.CONSISTENCY_FLOOR;
            const positiveRoi = roi >= 50;
            const allThree = heldShare && heldConsistency && positiveRoi;

            // Composite weights the four dials; share normalised onto a 0–100 band (10–28). Single source: _composite(ds).
            const composite = this._composite(ds);

            let performanceKey = `grade_stalled`;
            if (allThree && agility >= 70 && composite >= 74) performanceKey = `grade_leader`;
            else if (allThree && agility >= 55) performanceKey = `grade_balanced`;
            else if (heldConsistency && !heldShare) performanceKey = `grade_compliant`;
            else if (heldShare && !heldConsistency) performanceKey = `grade_rogue`;
            else if (heldShare && heldConsistency) performanceKey = `grade_heldline`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (allThree && agility >= 70) insights.push(window.mySimulation.t(`insight_leader`));
            else if (heldConsistency && !heldShare) insights.push(window.mySimulation.t(`insight_compliant`));
            else if (heldShare && !heldConsistency) insights.push(window.mySimulation.t(`insight_rogue`));
            else if (!allThree) insights.push(window.mySimulation.t(`insight_short`));

            if (!heldConsistency) insights.push(window.mySimulation.t(`insight_breach`));
            if (!heldShare) insights.push(window.mySimulation.t(`insight_shareloss`));
            if (roi < 40) insights.push(window.mySimulation.t(`insight_margin`));
            if (ds.opaque) insights.push(window.mySimulation.t(`insight_opaque`));
            if (allThree && agility >= 70) insights.push(window.mySimulation.t(`insight_complementary`));

            return {
                share: share,
                consistency: consistency,
                roi: roi,
                agility: agility,
                heldShare: heldShare,
                heldConsistency: heldConsistency,
                sound: allThree,
                opaque: ds.opaque,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.consistencyBreached) return window.mySimulation.t(`hint_breach`);
            if (ds.shareLost && state.currentPeriod >= 2) return window.mySimulation.t(`hint_share`);
            if (ds.roi < 35) return window.mySimulation.t(`hint_margin`);
            if (ds.opaque) return window.mySimulation.t(`hint_opaque`);
            if (state.currentPeriod >= 3 && ds.agility < 45) return window.mySimulation.t(`hint_agility`);
            if (ds.share >= this.SHARE_FLOOR && ds.consistency >= this.CONSISTENCY_FLOOR && ds.agility >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

